script:
// a 40 x 30 x 10 plate with a 6 mm hole drilled through its middle
const b = cuboid(40, 30, 10)
hole(b, { across: 6 })

// an L-shaped polygon sketched on the top plane, pulled up 12 mm
const sk = sketch('top')
sk.polygon([[0, 0], [40, 0], [40, 15], [15, 15], [15, 30], [0, 30]])
const shape = extrude(sk, 12)

// a 30 x 10 rectangle 25..55 mm from the axis, spun a full turn
const sk = sketch('front', 0)
sk.rect(30, 10, { at: [40, 0] })
const shape = revolve(sk, 360)

// a 40 x 40 x 10 base fused with a 6 mm post 20 mm tall
const base = cuboid(40, 40, 10, { at: [0, 0, 5] })
const post = cylinder(6, 20, { at: [0, 0, 10] })
union(base, post)

// a 40 x 40 x 20 block with a 20 x 20 square cutter that goes all the way through
const b = cuboid(40, 40, 20, { at: [0, 0, 10] })
const cutter = cuboid(20, 20, 30, { at: [0, 0, 15] })
subtract(b, cutter)

// a 20 x 20 x 10 block copied 3 times, 60 mm apart
const b = cuboid(20, 20, 10)
linearPattern(b, { count: 3, step: 60 })

// a 10 x 30 x 10 block, 25 mm from the axis, copied 4 times round Z
const b = cuboid(10, 30, 10, { at: [25, 0, 0] })
polarPattern(b, { count: 4, axis: 'z' })

// a sloppy 28.2 x 17 rectangle near (4,2): the rules dimension it 30 x 20 with its corner 5 right and 3 up of the origin
// solidcraft solves the dimensions, brep-rs and a closed form agree on the result
const sk = sketch('top')
sk.geom([
  { k: 'line', id: 1, a: [4.2, 2.1], b: [32.4, 2.1] },
  { k: 'line', id: 2, a: [32.4, 2.1], b: [32.4, 19.1] },
  { k: 'line', id: 3, a: [32.4, 19.1], b: [4.2, 19.1] },
  { k: 'line', id: 4, a: [4.2, 19.1], b: [4.2, 2.1] }
])
sk.rules([
  { k: 'coincident', a: 1, aEnd: 'b', b: 2, bEnd: 'a' },
  { k: 'coincident', a: 2, aEnd: 'b', b: 3, bEnd: 'a' },
  { k: 'coincident', a: 3, aEnd: 'b', b: 4, bEnd: 'a' },
  { k: 'coincident', a: 4, aEnd: 'b', b: 1, bEnd: 'a' },
  { k: 'horizontal', a: 1 },
  { k: 'vertical', a: 2 },
  { k: 'horizontal', a: 3 },
  { k: 'vertical', a: 4 },
  { k: 'distanceX', a: -1, aEnd: 'a', b: 1, bEnd: 'a', value: 5 },
  { k: 'distanceY', a: -1, aEnd: 'a', b: 1, bEnd: 'a', value: 3 },
  { k: 'distance', a: 1, aEnd: 'a', b: 1, bEnd: 'b', value: 30 },
  { k: 'distance', a: 2, aEnd: 'a', b: 2, bEnd: 'b', value: 20 }
])
const part = extrude(sk, 10)

// a slot: lines 40 mm long, 20 apart, closed by two R10 arcs that are tangent to them
// radius dimension + equal arcs + horizontal + length + one pinned centre
const sk = sketch('top')
sk.geom([
  { k: 'arc', id: 1, c: [0, 10], r: 10, a: [0, 0], b: [0, 20], sense: 'cw' },
  { k: 'arc', id: 2, c: [40, 10], r: 10, a: [40, 20], b: [40, 0], sense: 'cw' },
  { k: 'line', id: 3, a: [0, 20], b: [40, 20] },
  { k: 'line', id: 4, a: [40, 0], b: [0, 0] }
])
sk.rules([
  { k: 'coincident', a: 3, aEnd: 'a', b: 1, bEnd: 'b' },
  { k: 'tangent', a: 3, aEnd: 'a', b: 1, bEnd: 'b' },
  { k: 'coincident', a: 3, aEnd: 'b', b: 2, bEnd: 'a' },
  { k: 'tangent', a: 3, aEnd: 'b', b: 2, bEnd: 'a' },
  { k: 'coincident', a: 4, aEnd: 'a', b: 2, bEnd: 'b' },
  { k: 'tangent', a: 4, aEnd: 'a', b: 2, bEnd: 'b' },
  { k: 'coincident', a: 4, aEnd: 'b', b: 1, bEnd: 'a' },
  { k: 'tangent', a: 4, aEnd: 'b', b: 1, bEnd: 'a' },
  { k: 'radius', a: 1, value: 10 },
  { k: 'equal', a: 1, b: 2 },
  { k: 'horizontal', a: 3 },
  { k: 'distance', a: 3, aEnd: 'a', b: 3, bEnd: 'b', value: 40 },
  { k: 'lock', a: 1, aEnd: 'c' }
])
const part = extrude(sk, 10)

// a triangle: base 40 on the X axis from the origin, side 30, and 120 deg between side 1 and side 2
// (120 deg is the exterior angle: the interior corner is 60 deg)
const sk = sketch('top')
sk.geom([
  { k: 'line', id: 1, a: [0.5, 0.4], b: [39, 1] },
  { k: 'line', id: 2, a: [39, 1], b: [25, 26.5] },
  { k: 'line', id: 3, a: [25, 26.5], b: [0.5, 0.4] }
])
sk.rules([
  { k: 'coincident', a: 1, aEnd: 'b', b: 2, bEnd: 'a' },
  { k: 'coincident', a: 2, aEnd: 'b', b: 3, bEnd: 'a' },
  { k: 'coincident', a: 3, aEnd: 'b', b: 1, bEnd: 'a' },
  { k: 'horizontal', a: 1 },
  { k: 'coincident', a: 1, aEnd: 'a', b: -1, bEnd: 'a' },
  { k: 'distance', a: 1, aEnd: 'a', b: 1, bEnd: 'b', value: 40 },
  { k: 'distance', a: 2, aEnd: 'a', b: 2, bEnd: 'b', value: 30 },
  { k: 'angle', a: 1, b: 2, value: 120 }
])
const part = extrude(sk, 10)

// the same kind of dimensions through the handle API (sk.length, sk.across, sk.up)
// NOTE: these are solved by reSHape's own TS solver in solveDoc; solidcraft only sees the solved outline,
// so there is no solidcraft solver report for this sketch
const sk = sketch('top')
sk.polygon([[0, 0], [40, 0], [40, 25], [0, 25]])
sk.across(1)
sk.up(2)
sk.length(1, 40)
const shape = extrude(sk, 12)

// a rectangle with joins, horizontal/vertical and ONE length (40). Height and position are free.
// solidcraft keeps the drawn start (height 20) and reports the freedom
const sk = sketch('top')
sk.geom([
  { k: 'line', id: 1, a: [0, 0], b: [40, 0] },
  { k: 'line', id: 2, a: [40, 0], b: [40, 20] },
  { k: 'line', id: 3, a: [40, 20], b: [0, 20] },
  { k: 'line', id: 4, a: [0, 20], b: [0, 0] }
])
sk.rules([
  { k: 'coincident', a: 1, aEnd: 'b', b: 2, bEnd: 'a' },
  { k: 'coincident', a: 2, aEnd: 'b', b: 3, bEnd: 'a' },
  { k: 'coincident', a: 3, aEnd: 'b', b: 4, bEnd: 'a' },
  { k: 'coincident', a: 4, aEnd: 'b', b: 1, bEnd: 'a' },
  { k: 'horizontal', a: 1 },
  { k: 'vertical', a: 2 },
  { k: 'horizontal', a: 3 },
  { k: 'vertical', a: 4 },
  { k: 'distance', a: 1, aEnd: 'a', b: 1, bEnd: 'b', value: 40 }
])
const part = extrude(sk, 10)

// the same rectangle with width 40, height 20, and a second, contradictory width of 50
// solidcraft refuses the second dimension at command time; nothing is extruded
const sk = sketch('top')
sk.geom([
  { k: 'line', id: 1, a: [0, 0], b: [40, 0] },
  { k: 'line', id: 2, a: [40, 0], b: [40, 20] },
  { k: 'line', id: 3, a: [40, 20], b: [0, 20] },
  { k: 'line', id: 4, a: [0, 20], b: [0, 0] }
])
sk.rules([
  { k: 'coincident', a: 1, aEnd: 'b', b: 2, bEnd: 'a' },
  { k: 'coincident', a: 2, aEnd: 'b', b: 3, bEnd: 'a' },
  { k: 'coincident', a: 3, aEnd: 'b', b: 4, bEnd: 'a' },
  { k: 'coincident', a: 4, aEnd: 'b', b: 1, bEnd: 'a' },
  { k: 'horizontal', a: 1 },
  { k: 'vertical', a: 2 },
  { k: 'horizontal', a: 3 },
  { k: 'vertical', a: 4 },
  { k: 'lock', a: 1, aEnd: 'a' },
  { k: 'distanceX', a: 1, aEnd: 'a', b: 1, bEnd: 'b', value: 40 },
  { k: 'distanceY', a: 2, aEnd: 'a', b: 2, bEnd: 'b', value: 20 },
  { k: 'distanceX', a: 1, aEnd: 'a', b: 1, bEnd: 'b', value: 50 }
])
const part = extrude(sk, 10)

// the same rectangle with width 40 stated twice. brep-rs and FreeCAD accept this (redundant, builds); solidcraft is stricter
const sk = sketch('top')
sk.geom([
  { k: 'line', id: 1, a: [0, 0], b: [40, 0] },
  { k: 'line', id: 2, a: [40, 0], b: [40, 20] },
  { k: 'line', id: 3, a: [40, 20], b: [0, 20] },
  { k: 'line', id: 4, a: [0, 20], b: [0, 0] }
])
sk.rules([
  { k: 'coincident', a: 1, aEnd: 'b', b: 2, bEnd: 'a' },
  { k: 'coincident', a: 2, aEnd: 'b', b: 3, bEnd: 'a' },
  { k: 'coincident', a: 3, aEnd: 'b', b: 4, bEnd: 'a' },
  { k: 'coincident', a: 4, aEnd: 'b', b: 1, bEnd: 'a' },
  { k: 'horizontal', a: 1 },
  { k: 'vertical', a: 2 },
  { k: 'horizontal', a: 3 },
  { k: 'vertical', a: 4 },
  { k: 'lock', a: 1, aEnd: 'a' },
  { k: 'distanceX', a: 1, aEnd: 'a', b: 1, bEnd: 'b', value: 40 },
  { k: 'distanceY', a: 2, aEnd: 'a', b: 2, bEnd: 'b', value: 20 },
  { k: 'distanceX', a: 1, aEnd: 'a', b: 1, bEnd: 'b', value: 40 }
])
const part = extrude(sk, 10)

// round the edge where the top face meets the front face of a 40 x 40 x 20 block, radius 3
const b = cuboid(40, 40, 20)
round(b.edge('top', 'front'), 3)

// bevel the top-right edge of a 40 x 40 x 20 block by 3
const b = cuboid(40, 40, 20)
chamfer(b.edge('top', 'right'), 3)

// hollow a 40 x 40 x 20 block, 2 mm walls, open at the top
const b = cuboid(40, 40, 20)
shell(b, { wall: 2, open: 'top' })

// tilt the right face of a 40 x 40 x 20 block by 8 degrees, pulled along z, neutral plane at the bottom (z = -10)
const b = cuboid(40, 40, 20)
draft(b.face('right'), 8, { neutral: -10 })

// the rim of a 12 mm radius, 30 mm tall cylinder; solidcraft splits the wall into 2 halves and the rim into 2 half circles
const c = cylinder(12, 30)
round(c.edge('top', 'side'), 3)

// a 40 x 40 x 20 block with a 8 mm hole through the middle, then the top-right edge rounded 2
const b = cuboid(40, 40, 20)
const c = cylinder(4, 40, { at: [0, 0, 0] })
const d = subtract(b, c)
round(d.edge('top', 'right'), 2)

// the box edge is named against box1, the round is applied to the body after hole1 drilled it
const b = cuboid(40, 30, 10)
hole(b, { across: 6 })
round(b.edge('top', 'right'), 2)

// a 40 x 30 x 10 plate with a 10 mm hole through it, then hollowed 1 mm, open at the top (the top face is an annulus)
const b = cuboid(40, 30, 10)
hole(b, { across: 10 })
shell(b, { wall: 1, open: 'top' })

// a 60 x 40 x 12 plate, a 20 x 10 pocket 4 deep, and the rim edge along pocket wall 1 rounded 1
const plate = cuboid(60, 40, 12)
const sk2 = sketch('top', 6)
sk2.rect(20, 10, { at: [0, 0] })
const part = pocket(sk2, plate, 4)
round(part.edge('top', part.wall(sk2, 1)), 1)

const base = cuboid(40, 30, 10)
const post = extrude(sketch('top', 5).rect(10, 10), 20)
hole(base, { across: 6, at: [12, 0], counterbore: { across: 10, deep: 3 } })
const other = cuboid(10, 10, 10, { at: [30, 0, 0] })
round(other.edge('top', 'right'), 1)

// a closed hollow box, 2 mm walls: no face is opened
const b = cuboid(40, 40, 20)
shell(b, { wall: 2 })

// a channel 5 deep cut right across a block splits its top face into two coplanar pieces; "the top face" is then 2 faces
const b = cuboid(60, 40, 20)
const slot = cuboid(10, 50, 10, { at: [0, 0, 10] })
const d = subtract(b, slot)
shell(d, { wall: 2, open: 'top' })

// the wall of a round pocket is swept from an ARC; this demo resolves swept names over straight sketch edges only
const plate = cuboid(60, 40, 12)
const sk = sketch('top', 6)
sk.circle(8, { at: [0, 0] })
const part = pocket(sk, plate, 4)
round(part.edge('top', part.wall(sk, 1)), 1)

// ModelDoc (no script form: the script language cannot name b1's +z face on the union).
// b1 = box 40x30x10 centred at the origin, b2 = [10,10,8] at [0,0,9], union, shell 1 mm, open = b1.+z
{"version":1,"features":[{"id":"b1","kind":"box","size":[40,30,10],"center":[0,0,0]},{"id":"b2","kind":"box","size":[10,10,8],"center":[0,0,9]},{"id":"op1","kind":"combine","op":"union","targets":["b1","b2"]},{"id":"s1","kind":"shell","target":"op1","thickness":1,"open":{"cause":"primitive","feature":"b1","kind":"face","part":"+z"}}]}

